/**
 * Send a batch of 2 to 15 orders, all for a single trading pair. The whole batch is validated before submission -- one invalid order rejects the batch. Once submitted, individual orders that fail pre-match checks (e.g. insufficient funds) are rejected individually and the rest of the batch is still processed.
 *
 * **API Key Permissions Required:** `Orders and trades - Create & modify orders` and `Orders and trades - Cancel & close orders`
 */
export class AddOrderBatch {
  constructor(readonly core: HttpEndpoint<SpotMeta>) {}

  /** With `validate: false`: the parsed body as it came, typed `unknown`. */
  addOrderBatch(request: Request, options: CallOptions & { validate: false }): Promise<unknown>
  /**
   * Send a batch of 2 to 15 orders, all for a single trading pair. The whole batch is validated before submission -- one invalid order rejects the batch. Once submitted, individual orders that fail pre-match checks (e.g. insufficient funds) are rejected individually and the rest of the batch is still processed.
   *
   * **API Key Permissions Required:** `Orders and trades - Create & modify orders` and `Orders and trades - Cancel & close orders`
   *
   * @see https://docs.kraken.com/api-reference/trading/add-order-batch
   */
  addOrderBatch(request: Request, options?: CallOptions): Promise<OrderBatchAdded>
  async addOrderBatch(request: Request, options?: CallOptions): Promise<OrderBatchAdded> {
    return this.core.request({
      method: 'POST',
      path: '/0/private/AddOrderBatch',
      request,
      requestCodec: Request,
      responseCodec: OrderBatchAdded,
      meta: { signed: true },
      ...options,
    })
  }
}
